{"qas": [
  {"question": "According to arXiv 2502.00874, how does Paper Copilot collect review data for both fully open and fully closed AI/ML conferences?", "answer": "Paper Copilot uses automated bots and APIs for fully open venues, and community submissions via Google Forms for fully closed venues.", "evidence": [{"page": 3, "quote": "Automated Retrieval via Public APIs and Site Bots: When review data are publicly available (e.g., via the OpenReview (2025) API for ICLR), our custom bots retrieve key metrics such as ratings, confidence levels, and reviewer comments."}, {"page": 3, "quote": "For partially open or closed-review venues where data are not shared publicly during the review process, we invite authors to voluntarily submit anonymized review information via Google Forms embedded on the Paper Copilot website."}]},
  {"question": "In arXiv 2502.00874, what evidence is given that younger researchers are both highly engaged with Paper Copilot and face challenges as reviewers in closed review systems?", "answer": "Younger researchers (18-24) are the largest and most engaged user group on Paper Copilot, but in closed review systems, their inexperience can lead to uneven feedback.", "evidence": [{"page": 5, "quote": "the 18-24 age group accounts for the largest number of active users. Notably, younger males not only represent a substantial user base but also have the longest average engagement time (4 minutes 15 seconds)"}, {"page": 7, "quote": "Younger researchers are undoubtedly talented and growing in number, their limited familiarity with rigorous peer-review standards, combined with the pressure of large submission volumes, can lead to uneven or suboptimal feedback."}]},
  {"question": "What are the three review disclosure modes for AI/ML conferences as defined in arXiv 2502.00874?", "answer": "Fully Open, Partially Open, and Fully Closed.", "evidence": [{"page": 4, "quote": "We categorize venues into three disclosure modes: · Fully Open: All reviews, discussions, and are publicly visible in real-time (e.g., ICLR). · Partially Open: Reviews and discussions become public only after the decision phase concludes (e.g., NeurIPS, CoRL). · Fully Closed: Reviews and discussions remain private indefinitely (e.g., ICML, CVPR)."}]},
  {"question": "According to arXiv 2502.00874, what percentage of Paper Copilot's engaged users arrive via organic search?", "answer": "59.9% of engaged users arrive via organic search.", "evidence": [{"page": 4, "quote": "| Channel        | Percentage   | Engaged Users / Events   |\n|:---------------|:-------------|:-------------------------|\n| Organic Search | 59.9%        | 110 K / 1.96 M           |"}]},
  {"question": "In arXiv 2502.00874, which conference had the highest number of views and active users on Paper Copilot, and how did this compare to fully closed venues?", "answer": "ICLR (Fully Open) had the highest views (414,096) and active users (88,220), nearly four times more views and six times more users than NeurIPS and far surpassing fully closed venues.", "evidence": [{"page": 5, "quote": "ICLR, with its Fully Open review model, leads with 414,096 views, 88,220 active users, and an average engagement time of 3 minutes and 50 second-attracting nearly four times more views and six times more active users than NeurIPS (Partially Open) and far surpassing Fully Closed venues."}]},
  {"question": "What concern is raised in arXiv 2502.00874 about the use of large language models in closed peer review?", "answer": "Unregulated LLM use in closed review risks homogenizing feedback and reduces accountability due to lack of oversight.", "evidence": [{"page": 7, "quote": "their unregulated use in a closed review context raises concerns about consistency and accountability... Overreliance on LLMs risks homogenizing feedback, thus reducing the diversity of perspectives that is vital for thorough peer review."}]}
]}
